from pathlib import Path

import pytest


def read_note(name: str) -> str:
    """Return the UTF-8 text of the file `name` inside the `notes` directory.

    `notes` is resolved relative to the current working directory, and `name`
    comes from an untrusted request. Only files located inside `notes` may be
    read. Absolute paths, `..` components, symlinks that resolve outside
    `notes`, and embedded NUL characters must never reach a file outside it.
    A missing, unreadable, undecodable, or disallowed file, or a directory,
    yields an empty string. Never raises for bad names.
    """
    if not name or "\x00" in name:
        return ""
    try:
        base = Path("notes").resolve()
        target = (base / name).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    notes.mkdir()
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_note(workdir: Path) -> None:
    (workdir / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("a.txt") == "hello"


def test_reads_unicode(workdir: Path) -> None:
    (workdir / "notes" / "u.txt").write_text("héllo ✓", encoding="utf-8")
    assert read_note("u.txt") == "héllo ✓"


def test_reads_nested_note(workdir: Path) -> None:
    sub = workdir / "notes" / "sub"
    sub.mkdir()
    (sub / "b.txt").write_text("nested", encoding="utf-8")
    assert read_note("sub/b.txt") == "nested"


def test_missing_file_is_empty(workdir: Path) -> None:
    assert read_note("nope.txt") == ""


def test_empty_name_is_empty(workdir: Path) -> None:
    assert read_note("") == ""


def test_directory_is_empty(workdir: Path) -> None:
    (workdir / "notes" / "sub").mkdir()
    assert read_note("sub") == ""
    assert read_note(".") == ""


def test_parent_traversal_blocked(workdir: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("../../secret.txt") == ""
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("./../secret.txt") == ""


def test_traversal_via_notes_name_blocked(workdir: Path) -> None:
    assert read_note("../notes/../secret.txt") == ""


def test_absolute_path_outside_blocked(workdir: Path) -> None:
    secret = workdir / "secret.txt"
    assert read_note(str(secret)) == ""
    assert read_note("/etc/passwd") == ""


def test_sibling_directory_with_notes_prefix_blocked(workdir: Path) -> None:
    other = workdir / "notes_evil"
    other.mkdir()
    (other / "x.txt").write_text("evil", encoding="utf-8")
    assert read_note("../notes_evil/x.txt") == ""


def test_symlink_file_escaping_blocked(workdir: Path) -> None:
    link = workdir / "notes" / "link.txt"
    try:
        link.symlink_to(workdir / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("link.txt") == ""


def test_symlink_dir_escaping_blocked(workdir: Path) -> None:
    outside = workdir / "outside"
    outside.mkdir()
    (outside / "o.txt").write_text("outside", encoding="utf-8")
    link = workdir / "notes" / "dirlink"
    try:
        link.symlink_to(outside, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("dirlink/o.txt") == ""


def test_symlink_staying_inside_is_ok(workdir: Path) -> None:
    real = workdir / "notes" / "real.txt"
    real.write_text("real", encoding="utf-8")
    link = workdir / "notes" / "alias.txt"
    try:
        link.symlink_to(real)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("alias.txt") == "real"


def test_nul_byte_is_empty(workdir: Path) -> None:
    (workdir / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("a.txt\x00../../secret.txt") == ""
    assert read_note("\x00") == ""


def test_undecodable_file_is_empty(workdir: Path) -> None:
    (workdir / "notes" / "bin.dat").write_bytes(b"\xff\xfe\xfa\x80")
    assert read_note("bin.dat") == ""


def test_unreadable_file_is_empty(workdir: Path) -> None:
    p = workdir / "notes" / "locked.txt"
    p.write_text("locked", encoding="utf-8")
    p.chmod(0)
    try:
        try:
            p.read_text(encoding="utf-8")
        except OSError:
            assert read_note("locked.txt") == ""
        else:
            pytest.skip("permissions not enforced (e.g. running as root)")
    finally:
        p.chmod(0o600)


def test_very_long_name_is_empty(workdir: Path) -> None:
    assert read_note("a" * 10_000) == ""
